#include <stdio.h>

int main(void)
{
    int ch;
    int letters = 0, spaces = 0, digits = 0, others = 0;

    while ((ch = getchar()) != '\n' && ch != EOF) {
        if ((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z')) {
            letters++;
        } else if (ch == ' ') {
            spaces++;
        } else if (ch >= '0' && ch <= '9') {
            digits++;
        } else {
            others++;
        }
    }
    printf("%d %d %d %d\n", letters, spaces, digits, others);
    return 0;
}

#include <stdio.h>

int main(void)
{
    long long n, x, rev = 0;

    scanf("%lld", &n);
    x = n;
    while (x > 0) {
        rev = rev * 10 + x % 10;
        x /= 10;
    }
    if (rev == n) {
        printf("Yes\n");
    } else {
        printf("No\n");
    }
    return 0;
}

#include <stdio.h>

int main(void)
{
    int x, total = 0, c3 = 0, c5 = 0, c7 = 0;

    while (scanf("%d", &x) == 1 && x != 0) {
        int m3 = (x % 3 == 0);
        int m5 = (x % 5 == 0);
        int m7 = (x % 7 == 0);
        int cnt = m3 + m5 + m7;

        total++;
        if (cnt == 1) {
            if (m3) {
                c3++;
            } else if (m5) {
                c5++;
            } else {
                c7++;
            }
        }
    }
    if (total > 0) {
        printf("%.2f%%\n", 100.0 * c3 / total);
        printf("%.2f%%\n", 100.0 * c5 / total);
        printf("%.2f%%\n", 100.0 * c7 / total);
    } else {
        printf("0.00%%\n0.00%%\n0.00%%\n");
    }
    return 0;
}

