#include <stdio.h>

int main(void)
{
    long long n, sum;
    int times = 0;

    scanf("%lld", &n);
    sum = n;
    while (sum >= 10) {
        long long t = 0;
        long long x = sum;
        while (x > 0) {
            t += x % 10;
            x /= 10;
        }
        sum = t;
        times++;
    }
    printf("%lld %d\n", sum, times);
    return 0;
}

