#include <stdio.h>

int main(void)
{
    int n, i, j;

    scanf("%d", &n);
    for (i = 1; i <= n; i++) {
        for (j = 1; j <= n - i; j++) {
            putchar(' ');
        }
        for (j = 1; j <= 2 * i - 1; j++) {
            putchar('*');
        }
        putchar('\n');
    }
    for (i = n - 1; i >= 1; i--) {
        for (j = 1; j <= n - i; j++) {
            putchar(' ');
        }
        for (j = 1; j <= 2 * i - 1; j++) {
            putchar('*');
        }
        putchar('\n');
    }
    return 0;
}

#include <stdio.h>

int main(void)
{
    int n, i;

    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        int count = 0;
        int x;

        while (scanf("%d", &x) == 1 && x != -1) {
            int prime = 1;
            long long d;

            if (x < 2) {
                continue;
            }
            for (d = 2; d * d <= x; d++) {
                if (x % d == 0) {
                    prime = 0;
                    break;
                }
            }
            if (prime) {
                count++;
            }
        }
        printf("%d\n", count);
    }
    return 0;
}

