#include <stdio.h>

int main(void)
{
    int n, m, d;
    int found = 0;

    scanf("%d", &n);
    for (m = 2; m <= n; m++) {
        int sum = 0;

        for (d = 1; d < m; d++) {
            if (m % d == 0) {
                sum += d;
            }
        }
        if (sum == m) {
            found = 1;
            printf("%d = 1", m);
            for (d = 2; d < m; d++) {
                if (m % d == 0) {
                    printf(" + %d", d);
                }
            }
            printf("\n");
        }
    }
    if (!found) {
        printf("None\n");
    }
    return 0;
}

#include <stdio.h>

int main(void)
{
    int m, n, k;
    int x2, x3;

    scanf("%d%d", &m, &n);
    k = n - m;
    for (x2 = 0; x2 <= k; x2++) {
        for (x3 = 0; 2 * x3 <= k - x2; x3++) {
            int rest = k - x2 - 2 * x3;
            int x4, x1;

            if (rest % 3 != 0) {
                continue;
            }
            x4 = rest / 3;
            x1 = m - x2 - x3 - x4;
            if (x1 >= 0) {
                printf("%d %d %d\n", x2, x3, x4);
            }
        }
    }
    return 0;
}

#include <stdio.h>

int main(void)
{
    int l, c, i, j;
    int width, height;

    scanf("%d%d", &l, &c);
    width = 6 * c + 1;
    height = 4 * l + 1;
    for (j = 0; j < height; j++) {
        int type = j % 4;

        for (i = 0; i < width; i++) {
            if (type == 0) {
                putchar(i % 6 == 0 ? '|' : '*');
            } else if (type == 2) {
                if (i % 6 == 0) {
                    putchar('|');
                } else if (i % 6 == 3) {
                    putchar('+');
                } else {
                    putchar('-');
                }
            } else {
                putchar(i % 3 == 0 ? '|' : ' ');
            }
        }
        putchar('\n');
    }
    return 0;
}

#include <stdio.h>

int main(void)
{
    int n, x, y, z;
    int found = 0;

    scanf("%d", &n);
    for (x = 1; x <= n / 5; x++) {
        for (y = 1; y <= (n - 5 * x) / 3; y++) {
            z = n - x - y;
            if (z < 1 || z % 3 != 0) {
                continue;
            }
            if (5 * x + 3 * y + z / 3 == n) {
                printf("%d %d %d\n", x, y, z);
                found = 1;
            }
        }
    }
    if (!found) {
        printf("No solution.\n");
    }
    return 0;
}
